import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.0

    # Create a torso with moderate density for stability
    torso = sandbox.add_beam(
        x=start_x, y=start_y, width=1.5, height=0.4, angle=0, density=1.0
    )
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.2)

    # Define leg properties with increased density to improve traction
    leg_width = 0.1
    leg_height = 2.0
    leg_density = 1.5  # increases mass without exceeding the limit

    # Add left leg at an angle to push the torso forward
    left_leg = sandbox.add_beam(
        x=start_x - 1.0, y=start_y, width=leg_width, height=leg_height, angle=-math.pi/4, density=leg_density
    )
    sandbox.set_material_properties(left_leg, restitution=0.1, friction=0.2)

    # Add right leg at an angle to push the torso forward
    right_leg = sandbox.add_beam(
        x=start_x + 1.0, y=start_y, width=leg_width, height=leg_height, angle=-math.pi/4, density=leg_density
    )
    sandbox.set_material_properties(right_leg, restitution=0.1, friction=0.2)

    # Connect legs to torso using pivot joints (without limits to avoid clamping)
    joint_left = sandbox.add_joint(
        torso, left_leg, anchor_point=(start_x - 1.0, start_y), type='pivot'
    )
    joint_right = sandbox.add_joint(
        torso, right_leg, anchor_point=(start_x + 1.0, start_y), type='pivot'
    )

    return {"body": torso, "joints": [joint_left, joint_right]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    # Apply motor speed to both joints to drive forward motion
    for j in joints:
        sandbox.set_motor(j, motor_speed=-2.0, max_torque=200.0)
